  ('de00de02-0000-4000-8000-000000000577', 'de00de01-0000-4000-8000-000000000069', 'de00de00-0000-4000-8000-000000000060', 'barcelona', '2026-10-01', '10:00', '12:00', '阅读', 'El Born'),
