-- ---------- 3. 예시 후기(대상·상태는 trigger 가 정한다) ----------
insert into public.reviews (id, request_id, reviewer_id, target_id, rating_overall, rating_communication, rating_punctuality, rating_activity, body, activity_type)
select v.id::uuid, v.req::uuid, v.rev::uuid, v.host::uuid, v.o, v.c, v.p, v.a, v.body, v.act
from (values
  ('de00de03-0000-4000-8000-000000000001', 'de00de02-0000-4000-8000-000000000001', 'de00de01-0000-4000-8000-000000000074', 'de00de00-0000-4000-8000-000000000001', 5, 4, 5, 5, '行程很短，但把연남동逛得很充实。先问了我的喜好，再按喜好来带路。告诉我哪里适合拍照，照片都很好看。下次来还想再见面。', '探店咖啡馆'),
  ('de00de03-0000-4000-8000-000000000002', 'de00de02-0000-4000-8000-000000000002', 'de00de01-0000-4000-8000-000000000086', 'de00de00-0000-4000-8000-000000000001', 3, 2, 2, 3, 'Es gab eine kleine Route durch 서촌. Hat alle Fragen geduldig beantwortet. Guter Tipp fürs Mittagessen in der Nähe. Der Weg war für mich allerdings etwas weit.', 'Bäckereien'),
  ('de00de03-0000-4000-8000-000000000003', 'de00de02-0000-4000-8000-000000000003', 'de00de01-0000-4000-8000-000000000048', 'de00de00-0000-4000-8000-000000000001', 5, 4, 5, 4, 'A relaxed morning in Yeonnam-dong. Walked at my pace and never rushed me. Sitting down at Lane Bookshop for a chat was the best part.', 'Bakeries'),
  ('de00de03-0000-4000-8000-000000000004', 'de00de02-0000-4000-8000-000000000004', 'de00de01-0000-4000-8000-000000000008', 'de00de00-0000-4000-8000-000000000001', 5, 5, 5, 5, '첫 만남이라 긴장했는데 연남동에서 자연스럽게 시작했어요. 취향을 먼저 물어보고 거기에 맞춰 안내해 주셨어요. 연남 골목 서점에 들렀는데 현지 분이 아니면 몰랐을 곳이라 좋았어요.', '사진'),
  ('de00de03-0000-4000-8000-000000000005', 'de00de02-0000-4000-8000-000000000005', 'de00de01-0000-4000-8000-000000000080', 'de00de00-0000-4000-8000-000000000001', 4, 4, 4, 4, 'Pasamos unas 2 horas por 연남동. Muy fácil de hablar, nunca fue incómodo. Paramos en Neighborhood Noodles, un sitio que yo solo no habría encontrado. Me hizo querer aún más la ciudad.', 'Paseos por el barrio'),
  ('de00de03-0000-4000-8000-000000000006', 'de00de02-0000-4000-8000-000000000006', 'de00de01-0000-4000-8000-000000000051', 'de00de00-0000-4000-8000-000000000001', 5, 5, 5, 5, 'I was nervous meeting someone new, but Seochon made it easy. Shared stories you won''t find in any guidebook. Great tip on where to have lunch nearby. Recommended for solo travelers.', 'Photography'),
  ('de00de03-0000-4000-8000-000000000007', 'de00de02-0000-4000-8000-000000000007', 'de00de01-0000-4000-8000-000000000014', 'de00de00-0000-4000-8000-000000000001', 4, 3, 3, 3, '연남동에서 3시간 정도 같이 걸었어요. 제가 걷는 속도에 맞춰 주셔서 편하게 다녔어요. 특히 동네 국수집가 기억에 남아요. 만족스러운 만남이었어요.', '빈티지숍'),
  ('de00de03-0000-4000-8000-000000000008', 'de00de02-0000-4000-8000-000000000008', 'de00de01-0000-4000-8000-000000000068', 'de00de00-0000-4000-8000-000000000001', 5, 5, 5, 5, '初対面で緊張しましたが、연남동で自然に始められました。待ち合わせの時間をきちんと守ってくださり、連絡も早かったです。窓辺のカフェは一人なら通り過ぎていたと思います。おかげでこの街が好きになりました。', 'ベーカリー'),
  ('de00de03-0000-4000-8000-000000000009', 'de00de02-0000-4000-8000-000000000009', 'de00de01-0000-4000-8000-000000000075', 'de00de00-0000-4000-8000-000000000002', 5, 5, 5, 5, '行程很短，但把성수동逛得很充实。讲了很多旅游指南上没有的故事。连回去的路也照顾到了，很安心。推荐给一个人旅行的朋友。', '桌游'),
  ('de00de03-0000-4000-8000-000000000010', 'de00de02-0000-4000-8000-000000000010', 'de00de01-0000-4000-8000-000000000084', 'de00de00-0000-4000-8000-000000000002', 4, 4, 3, 4, 'Wir waren etwa 2 Stunden in 성수동 unterwegs. Sehr pünktlich und schon vorab schnell erreichbar. Das Gespräch bei Design Goods war der schönste Moment.', 'Brettspiele'),
  ('de00de03-0000-4000-8000-000000000011', 'de00de02-0000-4000-8000-000000000011', 'de00de01-0000-4000-8000-000000000036', 'de00de00-0000-4000-8000-000000000002', 5, 4, 5, 5, 'A relaxed morning in Seongsu-dong. Showed up right on time and replied quickly before we met. They even made sure I got back safely.', 'Hotspots'),
  ('de00de03-0000-4000-8000-000000000012', 'de00de02-0000-4000-8000-000000000012', 'de00de01-0000-4000-8000-000000000047', 'de00de00-0000-4000-8000-000000000002', 3, 3, 2, 2, 'It was a short trip, yet we covered a lot of Seongsu-dong. Shared stories you won''t find in any guidebook. I would have walked right past Design Goods without them. We had to change plans because of the weather, still fun.', 'Board games'),
  ('de00de03-0000-4000-8000-000000000013', 'de00de02-0000-4000-8000-000000000013', 'de00de01-0000-4000-8000-000000000019', 'de00de00-0000-4000-8000-000000000002', 5, 5, 5, 4, '성수동에서 3시간 정도 같이 걸었어요. 말투가 편안해서 처음 만났는데도 어색하지 않았어요. 공장 개조 카페에 들렀는데 현지 분이 아니면 몰랐을 곳이라 좋았어요.', '미술·전시'),
  ('de00de03-0000-4000-8000-000000000014', 'de00de02-0000-4000-8000-000000000014', 'de00de01-0000-4000-8000-000000000061', 'de00de00-0000-4000-8000-000000000002', 5, 5, 5, 5, '성수동でコースを考えてくださいました。先に好みを聞いて、それに合わせて案内してくださいました。帰り道まで気にかけてくださって安心でした。また来たらぜひお会いしたいです。', '地元グルメ'),
  ('de00de03-0000-4000-8000-000000000015', 'de00de02-0000-4000-8000-000000000015', 'de00de01-0000-4000-8000-000000000081', 'de00de00-0000-4000-8000-000000000002', 3, 3, 3, 3, 'Pasamos unas 3 horas por 성수동. Primero preguntó mis gustos y adaptó todo a ellos. Buen consejo para comer por la zona. Hubo algún momento incómodo al principio, que pasó rápido.', 'Sitios de moda'),
  ('de00de03-0000-4000-8000-000000000016', 'de00de02-0000-4000-8000-000000000016', 'de00de01-0000-4000-8000-000000000060', 'de00de00-0000-4000-8000-000000000002', 5, 5, 5, 5, '성수동を中心に4時間ほど歩きました。ガイドブックにない話をたくさん聞けました。工場跡カフェで休みながら話した時間が一番よかったです。おかげでこの街が好きになりました。', '音楽・ライブ'),
  ('de00de03-0000-4000-8000-000000000017', 'de00de02-0000-4000-8000-000000000017', 'de00de01-0000-4000-8000-000000000059', 'de00de00-0000-4000-8000-000000000002', 5, 5, 5, 5, '성수동でコースを考えてくださいました。待ち合わせの時間をきちんと守ってくださり、連絡も早かったです。写真映えするスポットを教えてもらい、きれいに撮れました。また来たらぜひお会いしたいです。', '話題のスポット'),
  ('de00de03-0000-4000-8000-000000000018', 'de00de02-0000-4000-8000-000000000018', 'de00de01-0000-4000-8000-000000000086', 'de00de00-0000-4000-8000-000000000002', 5, 5, 4, 5, 'Ich war vor dem ersten Treffen nervös, aber 성수동 war ein guter Einstieg. Sehr pünktlich und schon vorab schnell erreichbar. Factory Café war mein Lieblingsstopp. Beim nächsten Mal gern wieder.', 'Kunst & Ausstellungen'),
  ('de00de03-0000-4000-8000-000000000019', 'de00de02-0000-4000-8000-000000000019', 'de00de01-0000-4000-8000-000000000008', 'de00de00-0000-4000-8000-000000000003', 5, 5, 5, 5, '망원동 골목을 돌며 이런저런 이야기를 많이 나눴어요. 관광 책자에 없는 이야기를 많이 들려주셨어요. 돌아가는 길까지 챙겨 주셔서 마음이 놓였어요. 시간이 더 길었다면 좋았을 거예요.', '함께 요리하기'),
  ('de00de03-0000-4000-8000-000000000020', 'de00de02-0000-4000-8000-000000000020', 'de00de01-0000-4000-8000-000000000030', 'de00de00-0000-4000-8000-000000000003', 5, 5, 5, 5, '서촌에서 오전을 여유롭게 보냈어요. 관광 책자에 없는 이야기를 많이 들려주셨어요. 사진 찍기 좋은 자리를 짚어 주셔서 사진이 잘 나왔어요. 만족스러운 만남이었어요.', '함께 요리하기'),
  ('de00de03-0000-4000-8000-000000000021', 'de00de02-0000-4000-8000-000000000021', 'de00de01-0000-4000-8000-000000000006', 'de00de00-0000-4000-8000-000000000003', 4, 4, 4, 5, '망원동에서 3시간 정도 같이 걸었어요. 제가 걷는 속도에 맞춰 주셔서 편하게 다녔어요. 점심을 어디서 먹으면 좋은지도 알려 주셔서 도움이 됐어요. 덕분에 이 도시가 좋아졌어요.', '시장·길거리 음식'),
  ('de00de03-0000-4000-8000-000000000022', 'de00de02-0000-4000-8000-000000000022', 'de00de01-0000-4000-8000-000000000044', 'de00de00-0000-4000-8000-000000000003', 5, 5, 5, 5, 'We spent about 3 hours around Mangwon-dong. Very easy to talk to — it never felt awkward. Great tip on where to have lunch nearby. I just wish we had more time.', 'Markets & street food'),
  ('de00de03-0000-4000-8000-000000000023', 'de00de02-0000-4000-8000-000000000023', 'de00de01-0000-4000-8000-000000000015', 'de00de00-0000-4000-8000-000000000003', 5, 5, 4, 5, '망원동에서 2시간 정도 같이 걸었어요. 질문에 하나하나 친절하게 답해 주셨어요. 돌아가는 길까지 챙겨 주셔서 마음이 놓였어요. 시간이 더 길었다면 좋았을 거예요.', '시장·길거리 음식'),
  ('de00de03-0000-4000-8000-000000000024', 'de00de02-0000-4000-8000-000000000024', 'de00de01-0000-4000-8000-000000000017', 'de00de00-0000-4000-8000-000000000003', 4, 3, 4, 4, '짧은 일정이었는데 망원동 중심으로 알차게 돌아봤어요. 관광 책자에 없는 이야기를 많이 들려주셨어요. 사진 찍기 좋은 자리를 짚어 주셔서 사진이 잘 나왔어요. 덕분에 이 도시가 좋아졌어요.', '함께 요리하기'),
  ('de00de03-0000-4000-8000-000000000025', 'de00de02-0000-4000-8000-000000000025', 'de00de01-0000-4000-8000-000000000042', 'de00de00-0000-4000-8000-000000000003', 5, 5, 5, 4, 'A relaxed morning in Seochon. Shared stories you won''t find in any guidebook. Great tip on where to have lunch nearby. Recommended for solo travelers.', 'Local markets'),
  ('de00de03-0000-4000-8000-000000000026', 'de00de02-0000-4000-8000-000000000026', 'de00de01-0000-4000-8000-000000000009', 'de00de00-0000-4000-8000-000000000003', 4, 4, 4, 4, '서촌에서 2시간 정도 같이 걸었어요. 제가 걷는 속도에 맞춰 주셔서 편하게 다녔어요. 사진 찍기 좋은 자리를 짚어 주셔서 사진이 잘 나왔어요. 다만 이동 거리가 조금 길어서 힘들었어요.', '함께 요리하기'),
  ('de00de03-0000-4000-8000-000000000027', 'de00de02-0000-4000-8000-000000000027', 'de00de01-0000-4000-8000-000000000011', 'de00de00-0000-4000-8000-000000000003', 4, 4, 4, 4, '서촌 골목을 돌며 이런저런 이야기를 많이 나눴어요. 질문에 하나하나 친절하게 답해 주셨어요. 동네의 숨은 골목을 알려 주셔서 혼자 다닐 때와 완전히 달랐어요. 만족스러운 만남이었어요.', '함께 요리하기'),
  ('de00de03-0000-4000-8000-000000000028', 'de00de02-0000-4000-8000-000000000028', 'de00de01-0000-4000-8000-000000000087', 'de00de00-0000-4000-8000-000000000004', 5, 5, 5, 5, 'Ein entspannter Vormittag in 下北沢. Sehr pünktlich und schon vorab schnell erreichbar. Guter Tipp fürs Mittagessen in der Nähe. Ich hätte mir mehr Zeit gewünscht.', 'Musik & Shows'),
  ('de00de03-0000-4000-8000-000000000029', 'de00de02-0000-4000-8000-000000000029', 'de00de01-0000-4000-8000-000000000045', 'de00de00-0000-4000-8000-000000000004', 3, 3, 3, 3, 'It was a short trip, yet we covered a lot of Shimokitazawa. Showed up right on time and replied quickly before we met. Great tip on where to have lunch nearby. We had to change plans because of the weather, still fun.', 'Reading'),
  ('de00de03-0000-4000-8000-000000000030', 'de00de02-0000-4000-8000-000000000030', 'de00de01-0000-4000-8000-000000000011', 'de00de00-0000-4000-8000-000000000004', 4, 3, 4, 4, '첫 만남이라 긴장했는데 시모키타자와에서 자연스럽게 시작했어요. 취향을 먼저 물어보고 거기에 맞춰 안내해 주셨어요. 특히 골목 책방가 기억에 남아요. 또 오게 되면 다시 만나고 싶어요.', '카페 탐방'),
  ('de00de03-0000-4000-8000-000000000031', 'de00de02-0000-4000-8000-000000000031', 'de00de01-0000-4000-8000-000000000008', 'de00de00-0000-4000-8000-000000000004', 4, 3, 4, 4, '짧은 일정이었는데 시모키타자와 중심으로 알차게 돌아봤어요. 약속 시간을 정확히 지키셨고 연락도 빨랐어요. 사진 찍기 좋은 자리를 짚어 주셔서 사진이 잘 나왔어요. 혼자 여행하는 분께 추천해요.', '사진'),
  ('de00de03-0000-4000-8000-000000000032', 'de00de02-0000-4000-8000-000000000032', 'de00de01-0000-4000-8000-000000000023', 'de00de00-0000-4000-8000-000000000004', 5, 4, 5, 5, '시모키타자와 골목을 돌며 이런저런 이야기를 많이 나눴어요. 제가 걷는 속도에 맞춰 주셔서 편하게 다녔어요. 점심을 어디서 먹으면 좋은지도 알려 주셔서 도움이 됐어요.', '카페 탐방'),
  ('de00de03-0000-4000-8000-000000000033', 'de00de02-0000-4000-8000-000000000033', 'de00de01-0000-4000-8000-000000000031', 'de00de00-0000-4000-8000-000000000004', 4, 4, 3, 4, 'It was a short trip, yet we covered a lot of Shimokitazawa. Very easy to talk to — it never felt awkward. We stopped at Alley Books, which I''d never have found alone. I just wish we had more time.', 'Music & shows'),
  ('de00de03-0000-4000-8000-000000000034', 'de00de02-0000-4000-8000-000000000034', 'de00de01-0000-4000-8000-000000000022', 'de00de00-0000-4000-8000-000000000004', 5, 5, 4, 5, '시모키타자와 쪽으로 코스를 짜 주셔서 편하게 둘러봤어요. 취향을 먼저 물어보고 거기에 맞춰 안내해 주셨어요. 작은 커피집는 혼자였으면 그냥 지나쳤을 것 같아요. 덕분에 이 도시가 좋아졌어요.', '카페 탐방'),
  ('de00de03-0000-4000-8000-000000000035', 'de00de02-0000-4000-8000-000000000035', 'de00de01-0000-4000-8000-000000000006', 'de00de00-0000-4000-8000-000000000004', 5, 5, 5, 5, '시모키타자와 쪽으로 코스를 짜 주셔서 편하게 둘러봤어요. 말투가 편안해서 처음 만났는데도 어색하지 않았어요. 특히 골목 책방가 기억에 남아요. 혼자 여행하는 분께 추천해요.', '독서'),
  ('de00de03-0000-4000-8000-000000000036', 'de00de02-0000-4000-8000-000000000036', 'de00de01-0000-4000-8000-000000000021', 'de00de00-0000-4000-8000-000000000004', 5, 5, 5, 5, '시모키타자와 골목을 돌며 이런저런 이야기를 많이 나눴어요. 취향을 먼저 물어보고 거기에 맞춰 안내해 주셨어요. 특히 빈티지 잡화점가 기억에 남아요. 혼자 여행하는 분께 추천해요.', '독서'),
  ('de00de03-0000-4000-8000-000000000037', 'de00de02-0000-4000-8000-000000000037', 'de00de01-0000-4000-8000-000000000028', 'de00de00-0000-4000-8000-000000000004', 3, 3, 3, 3, '시모키타자와 골목을 돌며 이런저런 이야기를 많이 나눴어요. 질문에 하나하나 친절하게 답해 주셨어요. 점심을 어디서 먹으면 좋은지도 알려 주셔서 도움이 됐어요. 날씨 때문에 계획을 바꿨는데 그래도 즐거웠어요.', '독서'),
  ('de00de03-0000-4000-8000-000000000038', 'de00de02-0000-4000-8000-000000000038', 'de00de01-0000-4000-8000-000000000069', 'de00de00-0000-4000-8000-000000000005', 4, 4, 5, 4, '我们边逛蔵前的小巷边聊天。讲了很多旅游指南上没有的故事。最难忘的是Riverside Café。', '发现隐藏地点'),
  ('de00de03-0000-4000-8000-000000000039', 'de00de02-0000-4000-8000-000000000039', 'de00de01-0000-4000-8000-000000000077', 'de00de00-0000-4000-8000-000000000005', 5, 4, 5, 5, 'Estaba nervioso/a por conocer a alguien nuevo, pero 蔵前 lo hizo fácil. Caminó a mi ritmo sin meterme prisa. Me enseñó callejones escondidos que no tenían nada de ruta turística. Una experiencia muy buena.', 'Rincones escondidos'),
  ('de00de03-0000-4000-8000-000000000040', 'de00de02-0000-4000-8000-000000000040', 'de00de01-0000-4000-8000-000000000084', 'de00de00-0000-4000-8000-000000000005', 5, 5, 5, 5, 'Wir sind durch die Seitenstraßen von 蔵前 gelaufen und haben die ganze Zeit geredet. Sehr pünktlich und schon vorab schnell erreichbar. Wir waren bei Tiny Workshop Shop – allein hätte ich das nie gefunden. Ich hätte mir mehr Zeit gewünscht.', 'Lokale Küche'),
  ('de00de03-0000-4000-8000-000000000041', 'de00de02-0000-4000-8000-000000000041', 'de00de01-0000-4000-8000-000000000055', 'de00de00-0000-4000-8000-000000000005', 3, 3, 2, 3, '午前中、中目黒でのんびり過ごしました。先に好みを聞いて、それに合わせて案内してくださいました。写真映えするスポットを教えてもらい、きれいに撮れました。', 'サイクリング'),
  ('de00de03-0000-4000-8000-000000000042', 'de00de02-0000-4000-8000-000000000042', 'de00de01-0000-4000-8000-000000000051', 'de00de00-0000-4000-8000-000000000005', 5, 5, 5, 5, 'A relaxed morning in Kuramae. Showed up right on time and replied quickly before we met. Pointed out good photo spots and my pictures turned out great. I''d happily meet again next time.', 'Local eateries'),
  ('de00de03-0000-4000-8000-000000000043', 'de00de02-0000-4000-8000-000000000043', 'de00de01-0000-4000-8000-000000000089', 'de00de00-0000-4000-8000-000000000005', 4, 4, 4, 4, 'Wir waren etwa 3 Stunden in 蔵前 unterwegs. Super unkompliziert, nie unangenehm. Guter Tipp fürs Mittagessen in der Nähe. Der Zeitplan war etwas eng, insgesamt aber gut. Ich hätte mir mehr Zeit gewünscht.', 'Lokale Küche'),
  ('de00de03-0000-4000-8000-000000000044', 'de00de02-0000-4000-8000-000000000044', 'de00de01-0000-4000-8000-000000000031', 'de00de00-0000-4000-8000-000000000005', 3, 3, 2, 2, 'They built a little route around Nakameguro for me. Very easy to talk to — it never felt awkward. They showed me hidden alleys that felt nothing like a tourist route. We had to change plans because of the weather, still fun.', 'Bike rides'),
  ('de00de03-0000-4000-8000-000000000045', 'de00de02-0000-4000-8000-000000000045', 'de00de01-0000-4000-8000-000000000013', 'de00de00-0000-4000-8000-000000000005', 3, 2, 2, 3, '첫 만남이라 긴장했는데 구라마에에서 자연스럽게 시작했어요. 약속 시간을 정확히 지키셨고 연락도 빨랐어요. 강변 카페에서 쉬어 가며 이야기한 시간이 제일 좋았어요. 대화가 조금 어색한 순간도 있었지만 금방 풀렸어요.', '숨겨진 장소 발견'),
  ('de00de03-0000-4000-8000-000000000046', 'de00de02-0000-4000-8000-000000000046', 'de00de01-0000-4000-8000-000000000041', 'de00de00-0000-4000-8000-000000000005', 5, 4, 4, 5, 'I was nervous meeting someone new, but Kuramae made it easy. Asked what I like first, then tailored everything to it. We stopped at Riverside Café, which I''d never have found alone. Recommended for solo travelers.', 'Local eateries'),
  ('de00de03-0000-4000-8000-000000000047', 'de00de02-0000-4000-8000-000000000047', 'de00de01-0000-4000-8000-000000000053', 'de00de00-0000-4000-8000-000000000005', 5, 5, 4, 5, 'It was a short trip, yet we covered a lot of Kuramae. Walked at my pace and never rushed me. I would have walked right past Riverside Café without them. I just wish we had more time.', 'Bike rides'),
  ('de00de03-0000-4000-8000-000000000048', 'de00de02-0000-4000-8000-000000000048', 'de00de01-0000-4000-8000-000000000029', 'de00de00-0000-4000-8000-000000000005', 5, 5, 5, 5, '짧은 일정이었는데 나카메구로 중심으로 알차게 돌아봤어요. 말투가 편안해서 처음 만났는데도 어색하지 않았어요. 점심을 어디서 먹으면 좋은지도 알려 주셔서 도움이 됐어요. 혼자 여행하는 분께 추천해요.', '숨겨진 장소 발견'),
  ('de00de03-0000-4000-8000-000000000049', 'de00de02-0000-4000-8000-000000000049', 'de00de01-0000-4000-8000-000000000008', 'de00de00-0000-4000-8000-000000000006', 5, 5, 5, 5, '짧은 일정이었는데 나카자키초 중심으로 알차게 돌아봤어요. 약속 시간을 정확히 지키셨고 연락도 빨랐어요. 소품 가게는 혼자였으면 그냥 지나쳤을 것 같아요. 덕분에 이 도시가 좋아졌어요.', '카페 탐방'),
  ('de00de03-0000-4000-8000-000000000050', 'de00de02-0000-4000-8000-000000000050', 'de00de01-0000-4000-8000-000000000076', 'de00de00-0000-4000-8000-000000000006', 4, 4, 5, 3, '对方围绕中崎町安排了路线。讲了很多旅游指南上没有的故事。还推荐了附近吃午饭的地方，很有帮助。下次来还想再见面。', '古着店'),
  ('de00de03-0000-4000-8000-000000000051', 'de00de02-0000-4000-8000-000000000051', 'de00de01-0000-4000-8000-000000000077', 'de00de00-0000-4000-8000-000000000006', 5, 4, 4, 5, 'Pasamos unas 2 horas por 中崎町. Caminó a mi ritmo sin meterme prisa. Buen consejo para comer por la zona.', 'Fotografía'),
  ('de00de03-0000-4000-8000-000000000052', 'de00de02-0000-4000-8000-000000000052', 'de00de01-0000-4000-8000-000000000081', 'de00de00-0000-4000-8000-000000000006', 4, 4, 3, 3, 'Pasamos unas 2 horas por 堀江. Muy fácil de hablar, nunca fue incómodo. Me indicó buenos rincones para fotos y salieron genial. Repetiría sin dudarlo.', 'Tiendas vintage'),
  ('de00de03-0000-4000-8000-000000000053', 'de00de02-0000-4000-8000-000000000053', 'de00de01-0000-4000-8000-000000000031', 'de00de00-0000-4000-8000-000000000006', 4, 3, 4, 4, 'We wandered the side streets of Nakazakicho and chatted the whole time. Answered every question patiently. Old House Café was my favorite stop. I''d happily meet again next time.', 'Café hopping'),
  ('de00de03-0000-4000-8000-000000000054', 'de00de02-0000-4000-8000-000000000054', 'de00de01-0000-4000-8000-000000000053', 'de00de00-0000-4000-8000-000000000006', 5, 4, 5, 5, 'I was nervous meeting someone new, but Nakazakicho made it easy. Very easy to talk to — it never felt awkward. Old House Café was my favorite stop. It made me like the city even more.', 'Vintage shops'),
  ('de00de03-0000-4000-8000-000000000055', 'de00de02-0000-4000-8000-000000000055', 'de00de01-0000-4000-8000-000000000084', 'de00de00-0000-4000-8000-000000000006', 5, 5, 5, 4, 'Ich war vor dem ersten Treffen nervös, aber 中崎町 war ein guter Einstieg. Hat alle Fragen geduldig beantwortet. Small Shop war mein Lieblingsstopp. Empfehlenswert für Alleinreisende.', 'Vintage-Läden'),
  ('de00de03-0000-4000-8000-000000000056', 'de00de02-0000-4000-8000-000000000056', 'de00de01-0000-4000-8000-000000000015', 'de00de00-0000-4000-8000-000000000006', 5, 4, 4, 5, '나카자키초 쪽으로 코스를 짜 주셔서 편하게 둘러봤어요. 약속 시간을 정확히 지키셨고 연락도 빨랐어요. 사진 찍기 좋은 자리를 짚어 주셔서 사진이 잘 나왔어요. 덕분에 이 도시가 좋아졌어요.', '핫플레이스'),
  ('de00de03-0000-4000-8000-000000000057', 'de00de02-0000-4000-8000-000000000057', 'de00de01-0000-4000-8000-000000000003', 'de00de00-0000-4000-8000-000000000006', 5, 4, 5, 5, '나카자키초에서 3시간 정도 같이 걸었어요. 취향을 먼저 물어보고 거기에 맞춰 안내해 주셨어요. 고민가 카페에서 쉬어 가며 이야기한 시간이 제일 좋았어요. 또 오게 되면 다시 만나고 싶어요.', '카페 탐방'),
  ('de00de03-0000-4000-8000-000000000058', 'de00de02-0000-4000-8000-000000000058', 'de00de01-0000-4000-8000-000000000042', 'de00de00-0000-4000-8000-000000000006', 4, 3, 3, 4, 'It was a short trip, yet we covered a lot of Horie. Shared stories you won''t find in any guidebook. They showed me hidden alleys that felt nothing like a tourist route. The walking distance was a bit long for me.', 'Photography'),
  ('de00de03-0000-4000-8000-000000000059', 'de00de02-0000-4000-8000-000000000059', 'de00de01-0000-4000-8000-000000000055', 'de00de00-0000-4000-8000-000000000006', 5, 5, 5, 4, '午前中、堀江でのんびり過ごしました。待ち合わせの時間をきちんと守ってくださり、連絡も早かったです。写真映えするスポットを教えてもらい、きれいに撮れました。もっと時間があればよかったです。', '話題のスポット'),
  ('de00de03-0000-4000-8000-000000000060', 'de00de02-0000-4000-8000-000000000060', 'de00de01-0000-4000-8000-000000000053', 'de00de00-0000-4000-8000-000000000007', 5, 5, 5, 5, 'We wandered the side streets of Tenjinbashisuji and chatted the whole time. Shared stories you won''t find in any guidebook. Great tip on where to have lunch nearby. I just wish we had more time.', 'Cooking together'),
  ('de00de03-0000-4000-8000-000000000061', 'de00de02-0000-4000-8000-000000000061', 'de00de01-0000-4000-8000-000000000046', 'de00de00-0000-4000-8000-000000000007', 4, 4, 4, 4, 'We spent about 4 hours around Tenjinbashisuji. Walked at my pace and never rushed me. They showed me hidden alleys that felt nothing like a tourist route.', 'Local culture talk'),
  ('de00de03-0000-4000-8000-000000000062', 'de00de02-0000-4000-8000-000000000062', 'de00de01-0000-4000-8000-000000000016', 'de00de00-0000-4000-8000-000000000007', 5, 5, 4, 5, '덴진바시스지 쪽으로 코스를 짜 주셔서 편하게 둘러봤어요. 말투가 편안해서 처음 만났는데도 어색하지 않았어요. 점심을 어디서 먹으면 좋은지도 알려 주셔서 도움이 됐어요. 만족스러운 만남이었어요.', '현지 문화 이야기'),
  ('de00de03-0000-4000-8000-000000000063', 'de00de02-0000-4000-8000-000000000063', 'de00de01-0000-4000-8000-000000000065', 'de00de00-0000-4000-8000-000000000007', 4, 4, 4, 3, '天神橋筋の路地をめぐりながらたくさん話しました。話しやすくて、初めてでも気まずくなりませんでした。帰り道まで気にかけてくださって安心でした。日程は少しタイトでしたが、全体的には良かったです。一人旅の方におすすめです。', '市場・屋台'),
  ('de00de03-0000-4000-8000-000000000064', 'de00de02-0000-4000-8000-000000000064', 'de00de01-0000-4000-8000-000000000082', 'de00de00-0000-4000-8000-000000000007', 4, 4, 4, 4, 'Una mañana tranquila en 天神橋筋. Contó historias que no salen en ninguna guía. Me enseñó callejones escondidos que no tenían nada de ruta turística.', 'Cocinar juntos'),
  ('de00de03-0000-4000-8000-000000000065', 'de00de02-0000-4000-8000-000000000065', 'de00de01-0000-4000-8000-000000000056', 'de00de00-0000-4000-8000-000000000007', 4, 4, 4, 4, '短い日程でしたが、天神橋筋をしっかり回れました。質問に一つひとつ丁寧に答えてくださいました。街の隠れた路地を教えてもらえて、一人で歩くのとは全然違いました。最初は少し気まずい瞬間もありましたが、すぐ解けました。一人旅の方におすすめです。', '地元グルメ'),
  ('de00de03-0000-4000-8000-000000000066', 'de00de02-0000-4000-8000-000000000066', 'de00de01-0000-4000-8000-000000000040', 'de00de00-0000-4000-8000-000000000007', 4, 4, 4, 4, 'We wandered the side streets of Tenjinbashisuji and chatted the whole time. Asked what I like first, then tailored everything to it. They even made sure I got back safely. The schedule felt a little tight, but overall fine. A genuinely good experience.', 'Markets & street food'),
  ('de00de03-0000-4000-8000-000000000067', 'de00de02-0000-4000-8000-000000000067', 'de00de01-0000-4000-8000-000000000089', 'de00de00-0000-4000-8000-000000000007', 4, 4, 4, 4, 'Wir sind durch die Seitenstraßen von 天神橋筋 gelaufen und haben die ganze Zeit geredet. Super unkompliziert, nie unangenehm. Guter Tipp fürs Mittagessen in der Nähe. Eine wirklich gute Erfahrung.', 'Märkte & Streetfood'),
  ('de00de03-0000-4000-8000-000000000068', 'de00de02-0000-4000-8000-000000000068', 'de00de01-0000-4000-8000-000000000051', 'de00de00-0000-4000-8000-000000000007', 4, 4, 5, 4, 'A relaxed morning in Tenjinbashisuji. Shared stories you won''t find in any guidebook. Great tip on where to have lunch nearby.', 'Local culture talk'),
  ('de00de03-0000-4000-8000-000000000069', 'de00de02-0000-4000-8000-000000000069', 'de00de01-0000-4000-8000-000000000025', 'de00de00-0000-4000-8000-000000000007', 4, 5, 4, 4, '덴진바시스지 골목을 돌며 이런저런 이야기를 많이 나눴어요. 제가 걷는 속도에 맞춰 주셔서 편하게 다녔어요. 돌아가는 길까지 챙겨 주셔서 마음이 놓였어요.', '시장·길거리 음식'),
  ('de00de03-0000-4000-8000-000000000070', 'de00de02-0000-4000-8000-000000000070', 'de00de01-0000-4000-8000-000000000006', 'de00de00-0000-4000-8000-000000000007', 5, 5, 5, 5, '첫 만남이라 긴장했는데 덴진바시스지에서 자연스럽게 시작했어요. 말투가 편안해서 처음 만났는데도 어색하지 않았어요. 사진 찍기 좋은 자리를 짚어 주셔서 사진이 잘 나왔어요.', '시장·길거리 음식'),
  ('de00de03-0000-4000-8000-000000000071', 'de00de02-0000-4000-8000-000000000071', 'de00de01-0000-4000-8000-000000000003', 'de00de00-0000-4000-8000-000000000008', 5, 5, 5, 5, '크로이츠베르크에서 4시간 정도 같이 걸었어요. 말투가 편안해서 처음 만났는데도 어색하지 않았어요. 운하 옆 주말 시장는 혼자였으면 그냥 지나쳤을 것 같아요. 또 오게 되면 다시 만나고 싶어요.', '빈티지숍'),
  ('de00de03-0000-4000-8000-000000000072', 'de00de02-0000-4000-8000-000000000072', 'de00de01-0000-4000-8000-000000000002', 'de00de00-0000-4000-8000-000000000008', 5, 5, 5, 5, '크로이츠베르크 쪽으로 코스를 짜 주셔서 편하게 둘러봤어요. 약속 시간을 정확히 지키셨고 연락도 빨랐어요. 코너 로스터리에 들렀는데 현지 분이 아니면 몰랐을 곳이라 좋았어요. 시간이 더 길었다면 좋았을 거예요.', '미술·전시'),
  ('de00de03-0000-4000-8000-000000000073', 'de00de02-0000-4000-8000-000000000073', 'de00de01-0000-4000-8000-000000000062', 'de00de00-0000-4000-8000-000000000008', 4, 4, 4, 4, 'Kreuzbergを中心に3時間ほど歩きました。私の歩く速さに合わせてくださって楽でした。運河沿いの週末マーケットは一人なら通り過ぎていたと思います。', 'アート・展覧会'),
  ('de00de03-0000-4000-8000-000000000074', 'de00de02-0000-4000-8000-000000000074', 'de00de01-0000-4000-8000-000000000079', 'de00de00-0000-4000-8000-000000000008', 5, 5, 5, 5, 'Estaba nervioso/a por conocer a alguien nuevo, pero Kreuzberg lo hizo fácil. Respondió a todas mis preguntas con paciencia. Sin esta persona habría pasado de largo por Corner Roastery. Lo recomiendo a quien viaja solo.', 'Música y espectáculos'),
  ('de00de03-0000-4000-8000-000000000075', 'de00de02-0000-4000-8000-000000000075', 'de00de01-0000-4000-8000-000000000028', 'de00de00-0000-4000-8000-000000000008', 5, 5, 4, 5, '프리드리히샤인 쪽으로 코스를 짜 주셔서 편하게 둘러봤어요. 질문에 하나하나 친절하게 답해 주셨어요. 사진 찍기 좋은 자리를 짚어 주셔서 사진이 잘 나왔어요. 만족스러운 만남이었어요.', '빈티지숍'),
  ('de00de03-0000-4000-8000-000000000076', 'de00de02-0000-4000-8000-000000000076', 'de00de01-0000-4000-8000-000000000044', 'de00de00-0000-4000-8000-000000000008', 5, 5, 5, 4, 'It was a short trip, yet we covered a lot of Friedrichshain. Showed up right on time and replied quickly before we met. We stopped at Vintage Record Shop, which I''d never have found alone. Recommended for solo travelers.', 'Art & exhibitions'),
  ('de00de03-0000-4000-8000-000000000077', 'de00de02-0000-4000-8000-000000000077', 'de00de01-0000-4000-8000-000000000077', 'de00de00-0000-4000-8000-000000000008', 5, 4, 5, 5, 'Pasamos unas 4 horas por Friedrichshain. Caminó a mi ritmo sin meterme prisa. Buen consejo para comer por la zona. Repetiría sin dudarlo.', 'Conocer gente nueva'),
  ('de00de03-0000-4000-8000-000000000078', 'de00de02-0000-4000-8000-000000000078', 'de00de01-0000-4000-8000-000000000074', 'de00de00-0000-4000-8000-000000000008', 5, 4, 5, 5, '行程很短，但把Friedrichshain逛得很充实。会配合我的步调，一点也不赶。在Vintage Record Shop坐下来聊天的时光最棒。多亏他/她，我更喜欢这座城市了。', '音乐与演出'),
  ('de00de03-0000-4000-8000-000000000079', 'de00de02-0000-4000-8000-000000000079', 'de00de01-0000-4000-8000-000000000050', 'de00de00-0000-4000-8000-000000000008', 5, 4, 4, 5, 'I was nervous meeting someone new, but Friedrichshain made it easy. Walked at my pace and never rushed me. Vintage Record Shop was my favorite stop. I just wish we had more time.', 'Local markets'),
  ('de00de03-0000-4000-8000-000000000080', 'de00de02-0000-4000-8000-000000000080', 'de00de01-0000-4000-8000-000000000030', 'de00de00-0000-4000-8000-000000000008', 5, 4, 4, 5, '프리드리히샤인에서 오전을 여유롭게 보냈어요. 약속 시간을 정확히 지키셨고 연락도 빨랐어요. 빈티지 레코드 가게에 들렀는데 현지 분이 아니면 몰랐을 곳이라 좋았어요. 또 오게 되면 다시 만나고 싶어요.', '음악·공연'),
  ('de00de03-0000-4000-8000-000000000081', 'de00de02-0000-4000-8000-000000000081', 'de00de01-0000-4000-8000-000000000011', 'de00de00-0000-4000-8000-000000000009', 5, 5, 4, 4, '프렌츨라우어 베르크에서 2시간 정도 같이 걸었어요. 관광 책자에 없는 이야기를 많이 들려주셨어요. 동네의 숨은 골목을 알려 주셔서 혼자 다닐 때와 완전히 달랐어요. 덕분에 이 도시가 좋아졌어요.', '베이커리'),
  ('de00de03-0000-4000-8000-000000000082', 'de00de02-0000-4000-8000-000000000082', 'de00de01-0000-4000-8000-000000000028', 'de00de00-0000-4000-8000-000000000009', 5, 4, 5, 5, '프렌츨라우어 베르크 골목을 돌며 이런저런 이야기를 많이 나눴어요. 약속 시간을 정확히 지키셨고 연락도 빨랐어요. 중정 책방는 혼자였으면 그냥 지나쳤을 것 같아요.', '독서'),
  ('de00de03-0000-4000-8000-000000000083', 'de00de02-0000-4000-8000-000000000083', 'de00de01-0000-4000-8000-000000000025', 'de00de00-0000-4000-8000-000000000009', 4, 4, 4, 3, '프렌츨라우어 베르크에서 오전을 여유롭게 보냈어요. 말투가 편안해서 처음 만났는데도 어색하지 않았어요. 돌아가는 길까지 챙겨 주셔서 마음이 놓였어요. 대화가 조금 어색한 순간도 있었지만 금방 풀렸어요. 혼자 여행하는 분께 추천해요.', '공원·자연'),
  ('de00de03-0000-4000-8000-000000000084', 'de00de02-0000-4000-8000-000000000084', 'de00de01-0000-4000-8000-000000000014', 'de00de00-0000-4000-8000-000000000009', 5, 5, 5, 5, '짧은 일정이었는데 프렌츨라우어 베르크 중심으로 알차게 돌아봤어요. 질문에 하나하나 친절하게 답해 주셨어요. 동네의 숨은 골목을 알려 주셔서 혼자 다닐 때와 완전히 달랐어요. 시간이 더 길었다면 좋았을 거예요.', '독서'),
  ('de00de03-0000-4000-8000-000000000085', 'de00de02-0000-4000-8000-000000000085', 'de00de01-0000-4000-8000-000000000034', 'de00de00-0000-4000-8000-000000000009', 5, 4, 5, 5, 'I was nervous meeting someone new, but Prenzlauer Berg made it easy. Showed up right on time and replied quickly before we met. They showed me hidden alleys that felt nothing like a tourist route. Recommended for solo travelers.', 'Reading'),
